update public.institutions set
  feedback_summary_student = 'Отзывы сильно расходятся: часть студентов хвалит хорошее состояние корпусов и доброжелательных квалифицированных преподавателей. Одновременно встречаются очень резкие отзывы — жалобы на формальное проведение занятий, невыполнение обязанностей кураторами и старые упоминания о высоком уровне коррупции в вузе. Стоит уточнять актуальную ситуацию перед поступлением.',
  feedback_positive_highlights = '{"хорошее состояние корпусов","доброжелательные квалифицированные преподаватели"}',
  feedback_negative_highlights = '{"жалобы на формальность занятий и невыполнение обязанностей кураторами","старые упоминания о коррупции"}',
  feedback_based_on_count = 6, feedback_generated_at = now(), updated_at = now()
where name = 'Орловский государственный аграрный университет имени Н.В. Парахина' and city = 'Орёл';

update public.institutions set
  feedback_summary_student = 'Отзывы преимущественно тёплые: выпускники называют годы учёбы одними из лучших в жизни, хвалят преподавателей, которые «прекрасно знают предмет» и находят подход к каждому студенту, отмечают удобное центральное расположение и диплом РАНХиГС. Из критики — сожаления о преобразовании из самостоятельной академии в филиал, из-за чего часть сильных преподавателей ушла.',
  feedback_positive_highlights = '{"сильные преподаватели с индивидуальным подходом","удобное центральное расположение","диплом РАНХиГС"}',
  feedback_negative_highlights = '{"уход части преподавателей после реорганизации в филиал"}',
  feedback_based_on_count = 6, feedback_generated_at = now(), updated_at = now()
where name = 'Среднерусский институт управления - филиал Российской академии народного хозяйства и государственной службы при Президенте Российской Федерации' and city = 'Орёл';

update public.institutions set
