update public.institutions set
  feedback_summary_student = 'Небольшой филиал негосударственного вуза с давней историей на региональном рынке (более 25 лет работы). Студенты хвалят грамотный и доброжелательный преподавательский состав, доступную стоимость обучения и активную вовлечённость в научные конференции и конкурсы. Развёрнутой критики в открытых источниках почти не встречается.',
  feedback_positive_highlights = '{"грамотные и доброжелательные преподаватели","доступная стоимость обучения"}',
