update public.institutions set
  feedback_summary_student = 'Один из старейших музыкальных вузов России (более 130 лет). Студенты хвалят хорошо подобранный преподавательский состав, качественную очную подготовку и открытость руководства — отмечают, что директор лично готов встречаться со студентами по любым вопросам. Развёрнутой критики в открытых источниках немного.',
  feedback_positive_highlights = '{"качественная подготовка по музыкальным специальностям","открытое и отзывчивое руководство"}',
