  feedback_positive_highlights = '{"дружелюбный и доступный коллектив преподавателей","широкие возможности для самореализации"}',
  feedback_negative_highlights = '{"устаревшая инфраструктура старых корпусов","условия в общежитиях требуют улучшения"}',
  feedback_based_on_count = 7, feedback_generated_at = now(), updated_at = now()
where name = 'Тамбовский государственный технический университет' and city = 'Тамбов';

update public.institutions set
  feedback_summary_student = 'Крупный региональный университет: студенты хвалят понятное объяснение материала преподавателями, ухоженные и постепенно обновляемые корпуса, удобное расположение рядом с остановками и общежитиями, а также богатую инфраструктуру для досуга. Часть выпускников отмечает, что на отдельных старых кафедрах не хватает финансирования и оборудования, а качество образования и трудоустройство были выше в прошлом.',
  feedback_positive_highlights = '{"понятное объяснение материала преподавателями","ухоженные и обновляемые корпуса","богатая инфраструктура для досуга"}',
  feedback_negative_highlights = '{"недостаточное финансирование отдельных старых кафедр","снижение уровня трудоустройства по сравнению с прошлым"}',
  feedback_based_on_count = 8, feedback_generated_at = now(), updated_at = now()
where name = 'Тамбовский государственный университет имени Г. Р. Державина' and city = 'Тамбов';

